import { DEFAULT_DYNAMIC_SOUND_OPTIONS } from './default-options';
import { logAudioError } from './internal';
import { SoundController } from './sound-controller';
import { SoundInstance } from './sound-instance';
import { IDynamicSoundOptions } from './types';

export class DynamicTrackController {

    public dynamicTracks: string[] = [];
    public randomDynamic: boolean = false;
    public currentInstance?: SoundInstance;

    public constructor(protected controller: SoundController, protected category: string) { }

    /**
     * plays a continuous track from a list of segments either in sequence or a random order.
     * 
     * Supports only 1 playing at a time. You can access the currently playing segment with `this.currentInstance`
     * @param trackNames list of names of audio to play
     * @param options the options to control how the audio plays through
     */
    public playDynamic(trackNames: string[], options?: Partial<IDynamicSoundOptions>): void {
        if (this.currentInstance) {
            logAudioError('unable to call playDynamic when a dynamic track is already playing on this group');
            return;
        }

        const { randomPlayOrder, volume } = { ...DEFAULT_DYNAMIC_SOUND_OPTIONS, ...options };

        this.dynamicTracks = trackNames;
        this.randomDynamic = randomPlayOrder;

        if (this.dynamicTracks.length === 1) {
            this.currentInstance = this.controller.play(this.dynamicTracks[0], { category: this.category, loop: true, volume });
        } else {
            this.loopDynamic(volume);
        }
    }

    /**
     * stops audio started with playDynamic()
     */
    public stopDynamic(): void {
        this.currentInstance?.stop();
    }

    /**
     * Recursive function first called by playDynamicBGM(), plays a piece of music then when that finishes calls itself to play the next, etc...
     * @param volume the volume that the new segment should play at
     * @param trackName the name of the track to play, when omitted plays the first in the list
     */
    private loopDynamic(volume: number, trackName?: string): void {
        let track = trackName ?? (this.randomDynamic ? this.dynamicTracks.getRandom() : this.dynamicTracks[0]);

        this.currentInstance = this.controller.play(track, {
            category: this.category,
            volume,
            loop: false,
        });
        if (!this.currentInstance) {
            logAudioError('Failed to play dynamic track. Please ensure the track names provided to playDynamic are correct and that the audio files have been loaded');
            return;
        }
        this.currentInstance.once('end', () => {
            if (!this.currentInstance) {
                logAudioError('Unexpected error in DynamicTrackController: currentInstance is undefined in end event handler. This should never happen as the instance should still exist until after this handler finishes executing.');
                return;
            }
            const currentSoundName = this.currentInstance.sound.name;
            if (this.randomDynamic) {
                const splicedTracks = [...this.dynamicTracks];
                splicedTracks.splice(splicedTracks.indexOf(currentSoundName), 1); // remove the current track from the list
                const nextTrackName = splicedTracks.getRandom();
                this.loopDynamic(volume, nextTrackName);
            } else {
                const nextTrackIndex = (this.dynamicTracks.indexOf(currentSoundName) + 1) % this.dynamicTracks.length;
                track = this.dynamicTracks[nextTrackIndex];
                this.loopDynamic(volume, track);
            }
        });
    }
}